// 16진수 문자열 → Uint8Array
function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  }
  return bytes;
}
const FS_BASE    = `https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents`;

// ── Service Account JWT ───────────────────────────────────────────────────────
async function importPrivateKey(pem) {
  const content = pem
    .replace('-----BEGIN PRIVATE KEY-----', '')
    .replace('-----END PRIVATE KEY-----', '')
    .replace(/\s/g, '');
  const binary = atob(content);
  const bytes  = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return crypto.subtle.importKey(
    'pkcs8', bytes.buffer,
    { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
    false, ['sign']
  );
}
function b64url(str) {
  return btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');
}
function b64urlBuf(buf) {
  const bytes = new Uint8Array(buf);
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');
}
async function makeServiceJWT(sa) {
  const now = Math.floor(Date.now() / 1000);
  const hdr = b64url(JSON.stringify({ alg:'RS256', typ:'JWT' }));
  const pay = b64url(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/datastore https://www.googleapis.com/auth/firebase.messaging',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now, exp: now + 3600
  }));
  const key = await importPrivateKey(sa.private_key);
  const sig = await crypto.subtle.sign(
    'RSASSA-PKCS1-v1_5', key,
    new TextEncoder().encode(`${hdr}.${pay}`)
  );
  return `${hdr}.${pay}.${b64urlBuf(sig)}`;
}
async function makeFirebaseCustomToken(sa, uid) {
  const now = Math.floor(Date.now() / 1000);
  const hdr = b64url(JSON.stringify({ alg:'RS256', typ:'JWT' }));
  const pay = b64url(JSON.stringify({
    iss: sa.client_email, sub: sa.client_email,
    aud: 'https://identitytoolkit.googleapis.com/google.identity.identitytoolkit.v1.IdTokenFactory',
    uid, iat: now, exp: now + 3600
  }));
  const key = await importPrivateKey(sa.private_key);
  const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(`${hdr}.${pay}`));
  return `${hdr}.${pay}.${b64urlBuf(sig)}`;
}
async function getAccessToken(env) {
  if (!env.FIREBASE_SA_KEY) throw new Error('FIREBASE_SA_KEY not set');
  const sa  = JSON.parse(env.FIREBASE_SA_KEY);
  const jwt = await makeServiceJWT(sa);
  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${jwt}`
  });
  const data = await res.json();
  if (!data.access_token) throw new Error('Token error: ' + JSON.stringify(data));
  return data.access_token;
}

// ── Firestore REST helpers ────────────────────────────────────────────────────
async function fsQuery(token, collectionId, filters) {
  const res = await fetch(`${FS_BASE}:runQuery`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      structuredQuery: {
        from: [{ collectionId }],
        where: { compositeFilter: { op: 'AND', filters } }
      }
    })
  });
  return res.json();
}
async function fsPatch(token, docName, fields) {
  const mask = Object.keys(fields).map(f => `updateMask.fieldPaths=${f}`).join('&');
  const res  = await fetch(`${docName}?${mask}`, {
    method: 'PATCH',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ fields })
  });
  return res.json();
}
async function fsAdd(token, collectionId, fields) {
  const res = await fetch(`${FS_BASE}/${collectionId}`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ fields })
  });
  return res.json();
}

async function fsGet(token, collectionId, docId) {
  const res = await fetch(`${FS_BASE}/${collectionId}/${docId}`, {
    headers: { 'Authorization': `Bearer ${token}` }
  });
  return res.json();
}

// ── No-Show Penalty Job ───────────────────────────────────────────────────────
// 승인 후 48시간 경과, 노쇼 경고 발생, 아직 완료 안된 apply → trustScore -10
async function runNoShowPenaltyJob(env) {
  try {
    const token = await getAccessToken(env);
    const cutoff = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();
    const rows = await fetch(`${FS_BASE}:runQuery`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ structuredQuery: {
        from: [{ collectionId: 'yongcha_applies' }],
        where: { compositeFilter: { op: 'AND', filters: [
          { fieldFilter: { field: { fieldPath: 'status' }, op: 'EQUAL', value: { stringValue: 'approved' } } },
          { fieldFilter: { field: { fieldPath: 'noShowWarned' }, op: 'EQUAL', value: { booleanValue: true } } },
          { fieldFilter: { field: { fieldPath: 'penaltyApplied' }, op: 'EQUAL', value: { booleanValue: false } } },
          { fieldFilter: { field: { fieldPath: 'noShowWarnedAt' }, op: 'LESS_THAN', value: { timestampValue: cutoff } } }
        ] } }
      } })
    }).then(r => r.json()).catch(() => []);
    let penalized = 0;
    for (const row of (rows || [])) {
      if (!row.document) continue;
      const f = row.document.fields || {};
      const driverId = f.driverId?.stringValue;
      const applyId = row.document.name.split('/').pop();
      if (!driverId) continue;
      const userDoc = await fetch(`${FS_BASE}/yongcha_users/${driverId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      }).then(r => r.json()).catch(() => ({}));
      const uf = userDoc.fields || {};
      const curScore = parseInt(uf.trustScore?.integerValue || uf.trustScore?.doubleValue || 60);
      const newScore = Math.max(0, curScore - 10);
      const noShowCount = parseInt(uf.noShowCount?.integerValue || 0) + 1;
      await fsPatch(token, `${FS_BASE}/yongcha_users/${driverId}`, {
        trustScore: { integerValue: newScore },
        noShowCount: { integerValue: noShowCount }
      }).catch(() => {});
      await fsPatch(token, `${FS_BASE}/yongcha_applies/${applyId}`, {
        penaltyApplied: { booleanValue: true },
        status: { stringValue: 'noshow' }
      }).catch(() => {});
      penalized++;
    }
    console.log(`[cron-noshowpenalty] penalized=${penalized}`);
  } catch (e) {
    console.error('[cron-noshowpenalty]', e.message);
  }
}

// ── Settlement Alert Job ──────────────────────────────────────────────────────
// 정산 pending 7일 초과 → 대리점에 FCM 알림
async function runSettlementAlertJob(env) {
  try {
    const token = await getAccessToken(env);
    const cutoff = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const rows = await fetch(`${FS_BASE}:runQuery`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ structuredQuery: {
        from: [{ collectionId: 'yongcha_settlements' }],
        where: { compositeFilter: { op: 'AND', filters: [
          { fieldFilter: { field: { fieldPath: 'status' }, op: 'EQUAL', value: { stringValue: 'pending' } } },
          { fieldFilter: { field: { fieldPath: 'alertSent' }, op: 'EQUAL', value: { booleanValue: false } } },
          { fieldFilter: { field: { fieldPath: 'createdAt' }, op: 'LESS_THAN', value: { timestampValue: cutoff } } }
        ] } }
      } })
    }).then(r => r.json()).catch(() => []);
    let alerted = 0;
    const fcmUrl = 'https://fcm.googleapis.com/v1/projects/mbti-logistics/messages:send';
    for (const row of (rows || [])) {
      if (!row.document) continue;
      const f = row.document.fields || {};
      const settleId = row.document.name.split('/').pop();
      const agencyId = f.agencyId?.stringValue;
      const driverName = f.driverName?.stringValue || '기사';
      const amount = parseInt(f.amount?.integerValue || f.amount?.doubleValue || 0);
      if (!agencyId) continue;
      const tokenRows = await fetch(`${FS_BASE}:runQuery`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ structuredQuery: {
          from: [{ collectionId: 'yongcha_fcm_tokens' }],
          where: { fieldFilter: { field: { fieldPath: 'uid' }, op: 'EQUAL', value: { stringValue: agencyId } } },
          limit: 3
        } })
      }).then(r => r.json()).catch(() => []);
      for (const tr of (tokenRows || [])) {
        if (!tr.document) continue;
        const fcmToken = tr.document.fields?.token?.stringValue;
        if (!fcmToken) continue;
        await fetch(fcmUrl, {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ message: {
            token: fcmToken,
            notification: { title: '정산 미지급 알림', body: `${driverName}님 정산 ${amount.toLocaleString()}원이 7일째 미지급 상태예요` },
            data: { type: 'settle_overdue', settleId }
          } })
        }).catch(() => {});
      }
      await fsPatch(token, `${FS_BASE}/yongcha_settlements/${settleId}`, {
        alertSent: { booleanValue: true },
        alertSentAt: { timestampValue: new Date().toISOString() }
      }).catch(() => {});
      alerted++;
    }
    console.log(`[cron-settleAlert] alerted=${alerted}`);
  } catch (e) {
    console.error('[cron-settleAlert]', e.message);
  }
}

// ── Expire Job ────────────────────────────────────────────────────────────────
async function runExpireJob(env) {
  const token = await getAccessToken(env);
  const now   = new Date();
  const today = now.toISOString().slice(0, 10);
  const d7 = new Date(now);
  d7.setDate(d7.getDate() + 7);
  const d7str = d7.toISOString().slice(0, 10);
  console.log(`[cron-expire] ${today}, D7: ${d7str}`);
  const companies = await fsQuery(token, 'companies', []);
  let expired=0, warned=0, renewed=0;
  for (const row of companies) {
    if (!row.document) continue;
    const fields = row.document.fields || {};
    const docName = row.document.name;
    const companyId = docName.split('/').pop();
    const companyName = fields.companyName?.stringValue || fields.name?.stringValue || '';
    const adminEmail = fields.adminEmail?.stringValue || fields.email?.stringValue || '';
    const subs = fields.subscriptions?.mapValue?.fields || {};
    const products = ['donway', 'qr', 'inventory', 'kiosk'];
    let needUpdate = false;
    const updatedSubs = JSON.parse(JSON.stringify(subs));
    for (const product of products) {
      const sub = subs[product]?.mapValue?.fields;
      if (!sub) continue;
      const active = sub.active?.booleanValue;
      if (!active) continue;
      const expiry = sub.expiry?.stringValue || '';
      if (!expiry) continue;
      if (expiry < today) {
        updatedSubs[product] = { mapValue: { fields: { ...sub, active: { booleanValue: false }, expiredAt: { stringValue: today } } } };
        needUpdate = true; expired++;
        await sendWelcomeEmail(env, { email: adminEmail, companyName, tempPassword: '', planType: 'expired', planLabel: product, loginUrl: 'https://donway.ai.kr/settle' }).catch(()=>{});
        await fsAdd(token, 'alimtalk_queue', { type:{stringValue:'sub_expired'}, companyId:{stringValue:companyId}, companyName:{stringValue:companyName}, email:{stringValue:adminEmail}, product:{stringValue:product}, expiry:{stringValue:expiry}, status:{stringValue:'pending'}, createdAt:{stringValue:now.toISOString()} }).catch(()=>{});
      } else if (expiry === d7str) {
        warned++;
        await fsAdd(token, 'alimtalk_queue', { type:{stringValue:'sub_renew_warning'}, companyId:{stringValue:companyId}, companyName:{stringValue:companyName}, email:{stringValue:adminEmail}, product:{stringValue:product}, expiry:{stringValue:expiry}, daysLeft:{integerValue:7}, status:{stringValue:'pending'}, createdAt:{stringValue:now.toISOString()} }).catch(()=>{});
        if (env.EMAIL_API_KEY) {
          const html = `<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px"><div style="font-size:24px;text-align:center;margin-bottom:12px"></div><div style="font-size:18px;font-weight:900;text-align:center;margin-bottom:8px">구독 만료 7일 전</div><p style="font-size:13px;color:#555;text-align:center;margin-bottom:20px"><b>${companyName}</b>의 <b>${product}</b> 구독이<br><b>${expiry}</b>에 만료됩니다.</p><a href="tel:051-711-3103" style="display:block;text-align:center;background:linear-gradient(90deg,#0066ff,#00d4ff);color:#fff;padding:14px;border-radius:12px;font-size:14px;font-weight:900;text-decoration:none">051-711-3103 갱신 문의</a></div>`;
          await fetch('https://api.resend.com/emails', { method:'POST', headers:{'Authorization':`Bearer ${env.EMAIL_API_KEY}`,'Content-Type':'application/json'}, body: JSON.stringify({ from:'DONWAY <all@donway.ai.kr>', to:[adminEmail], subject:`[DONWAY] ${companyName} 구독 만료 7일 전 알림`, html }) }).catch(()=>{});
        }
      }
    }
    if (needUpdate) {
      await fsPatch(token, `https://firestore.googleapis.com/v1/projects/mbti-logistics/databases/(default)/documents/companies/${companyId}`, { subscriptions: { mapValue: { fields: updatedSubs } } }).catch(e => console.error('[patch]', e.message));
    }
  }
  await fsAdd(token, 'cron_logs', { type:{stringValue:'expire_check'}, date:{stringValue:today}, expired:{integerValue:expired}, warned:{integerValue:warned}, renewed:{integerValue:renewed}, createdAt:{stringValue:now.toISOString()} }).catch(()=>{});
  return { expired, warned, renewed };
}

// ── Cron: alimtalk_queue 처리 (Aligo SMS/알림톡) ─────────────────────────────
async function processAlimtalkQueue(env) {
  const token = await getAccessToken(env);
  const sender = env.ALIGO_SENDER || '05171133103';
  if (!env.ALIGO_KEY || !env.ALIGO_USER_ID) {
    console.log('[alimtalk-queue] Aligo 키 미설정, 건너뜀');
    return;
  }
  // pending 항목 조회
  const rawRows = await fsQuery(token, 'alimtalk_queue', [
    { fieldFilter: { field: { fieldPath: 'status' }, op: 'EQUAL', value: { stringValue: 'pending' } } }
  ]).catch(() => []);
  const rows = (Array.isArray(rawRows) ? rawRows : []).filter(r => r.document);
  if (!rows.length) return;
  console.log(`[alimtalk-queue] ${rows.length}건 처리`);

  async function aligoSms(phone, text) {
    const p = new URLSearchParams({
      key: env.ALIGO_KEY, user_id: env.ALIGO_USER_ID,
      sender, receiver: phone.replace(/[^0-9]/g, ''),
      msg: text, msg_type: text.length > 90 ? 'LMS' : 'SMS'
    });
    return fetch('https://apis.aligo.in/send/', {
      method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: p.toString()
    }).then(r => r.json()).catch(() => ({ result_code: -1 }));
  }

  async function getCompanyPhone(companyId) {
    const doc = await fsGet(token, 'companies', companyId).catch(() => null);
    if (!doc) return '';
    const f = doc.fields || {};
    return (f.phone?.stringValue || f.settlementPhone?.stringValue || '').replace(/[^0-9]/g, '');
  }

  for (const row of rows) {
    const docId = row.document.name.split('/').pop();
    const f = row.document.fields || {};
    const type = f.type?.stringValue || f.type || '';
    const companyName = f.companyName?.stringValue || f.companyName || '';
    const companyId = f.companyId?.stringValue || f.companyId || '';
    let ok = false;
    try {
      const phone = await getCompanyPhone(companyId);
      let text = '';
      if (type === 'sub_expired') {
        const product = f.product?.stringValue || f.product || 'DONWAY';
        text = `[DONWAY] ${companyName}님, ${product} 구독이 만료되었습니다. 서비스 이용을 위해 구독을 갱신해 주세요.\n갱신: https://donway.ai.kr/settle`;
      } else if (type === 'sub_renew_warning') {
        const product = f.product?.stringValue || f.product || 'DONWAY';
        const daysLeft = f.daysLeft?.integerValue || f.daysLeft || 7;
        const expiry = f.expiry?.stringValue || f.expiry || '';
        text = `[DONWAY] ${companyName}님, ${product} 구독이 ${daysLeft}일 후(${expiry}) 만료됩니다. 만료 전 갱신을 권장드립니다.\n갱신: https://donway.ai.kr/settle`;
      } else if (type === 'new_payment') {
        const plan = f.plan?.stringValue || f.plan || '';
        const amount = f.amount?.integerValue || f.amount || 0;
        const expireDate = f.expireDate?.stringValue || f.expireDate || '';
        text = `[DONWAY] ${companyName}님, 결제가 완료되었습니다.\n플랜: ${plan}\n금액: ${Number(amount).toLocaleString()}원\n만료일: ${expireDate}\n이용해 주셔서 감사합니다.`;
      }
      if (text && phone) {
        const res = await aligoSms(phone, text);
        ok = res.result_code == 1;
      } else {
        ok = true; // 전화번호 없으면 건너뜀 (이메일로 대체됨)
      }
    } catch(e) {
      console.error('[alimtalk-queue]', type, e.message);
    }
    // 상태 업데이트
    await fsPatch(token, `${FS_BASE}/alimtalk_queue/${docId}`, {
      status: { stringValue: ok ? 'sent' : 'failed' },
      processedAt: { stringValue: new Date().toISOString() }
    }).catch(() => {});
  }
  console.log(`[alimtalk-queue] 처리 완료`);
}


// ── Fetch Handler ─────────────────────────────────────────────────────────────

// ── Cron: GitHub → KV 자동 동기화 ─────────────────────────────────────────
async function syncKVFromGitHub(env) {
  const e = env || _env_ref;
  if (!e || !e.DONWAY_ASSETS) return { ok: false, reason: 'no KV' };
  
  const GITHUB_RAW = 'https://raw.githubusercontent.com/kimdh4790-cpu/mbti-logistics/main';
  const FILES = [
    'settle.html', 'inventory.html', 'qrpos.html', 'kiosk.html',
    'mbtico_hub.html', 'join.html', 'admin_sub.html', 'add.html', 'wait.html', 'order.html', 'donway_landing.html'
  ];
  
  const results = [];
  for (const file of FILES) {
    try {
      const resp = await fetch(`${GITHUB_RAW}/${file}?v=${Date.now()}`, {
        headers: { 'Cache-Control': 'no-cache' }
      });
      if (!resp.ok) { results.push({ file, ok: false, status: resp.status }); continue; }
      const text = await resp.text();
      await e.DONWAY_ASSETS.put(file, text);
      results.push({ file, ok: true, size: text.length });
    } catch(err) {
      results.push({ file, ok: false, error: err.message });
    }
  }
  console.log('[Cron] KV 동기화:', JSON.stringify(results.map(r => r.file + ':' + (r.ok ? '✅' : '❌'))));
  return { ok: true, results };
}


// subscriptions 구조: donway/filo/mbtico modules 배열로 메뉴 제어
