          from: (services||[]).some(s=>['filo','dine','table_order','kiosk','inventory'].includes(s))
            ? 'FILO·DINE <filo-dine@donway.ai.kr>'
            : 'DONWAY <all@donway.ai.kr>',
          to: (services||[]).some(s=>['filo','dine','table_order','kiosk','inventory'].includes(s))
