/* ══ 차종 — 하이탑 / 로우탑 두 가지로 통일 ══════════════════════
   과거 데이터에 '1톤 하이탑' 처럼 톤수가 붙은 값이 섞여 있어
   그대로 비교하면 매칭이 전부 실패한다 → 항상 _yCarNorm 으로 정규화해서 비교. */
var CAR_TYPES=['하이탑','로우탑'];
function _yCarNorm(v){
  var s=String(v==null?'':v).trim();
  if(!s)return '';
  if(s.indexOf('하이탑')!==-1)return '하이탑';
  if(s.indexOf('로우탑')!==-1)return '로우탑';
  if(s==='무관')return '';
  return s;
}
function _yCarOptions(sel,includeAny){
  var list=includeAny?CAR_TYPES.concat(['무관']):CAR_TYPES;
  return '<option value="">차종 선택</option>'+list.map(function(v){
    return '<option value="'+v+'"'+(_yCarNorm(sel)===_yCarNorm(v)?' selected':'')+'>'+v+'</option>';
  }).join('');
}

function _yLogin(){
  var e=(document.getElementById('l-email').value||'').trim();
  var p=(document.getElementById('l-pw').value||'').trim();
  var err=document.getElementById('l-err');
  var btn=document.getElementById('l-btn');
  if(!e||!p){err.textContent='이메일과 비밀번호를 입력하세요';err.style.display='block';return;}
  err.style.display='none';
  btn.textContent='로그인 중...';btn.disabled=true;
  _auth.signInWithEmailAndPassword(e,p).catch(function(ex){
    btn.textContent='로그인';btn.disabled=false;
    var c=ex.code||'';
    err.textContent=c==='auth/wrong-password'||c==='auth/invalid-credential'?'비밀번호가 틀렸어요':
                    c==='auth/user-not-found'?'없는 계정이에요':
                    c==='auth/too-many-requests'?'잠시 후 다시 시도하세요':
                    c==='auth/invalid-email'?'이메일 형식을 확인하세요':
                    '오류: '+c;
    err.style.display='block';
  });
}

function _yRegister(){
  var n=(document.getElementById('r-name').value||'').trim();
  var e=(document.getElementById('r-email').value||'').trim();
  var ph=(document.getElementById('r-phone').value||'').trim();
  var rg=(document.getElementById('r-region').value||'').trim();
  var p=(document.getElementById('r-pw').value||'').trim();
  var err=document.getElementById('r-err');
  var btn=document.getElementById('r-btn');
  if(!n||!e||!ph||!rg||!p){err.textContent='모든 항목을 입력하세요';err.style.display='block';return;}
  if(p.length<6){err.textContent='비밀번호는 6자 이상';err.style.display='block';return;}
  err.style.display='none';btn.textContent='가입 중...';btn.disabled=true;
  _auth.createUserWithEmailAndPassword(e,p).then(function(c){
    var userType=ADMINS.indexOf(e)>=0?'admin':_regType;
    var _doc={
      uid:c.user.uid,type:userType,name:n,email:e,phone:ph,region:rg,carType:(document.getElementById('r-cartype')||{}).value||'',
      carFuelType:(document.getElementById('r-carfuel')||{}).value||'휘발유',
      rating:0,reviewCount:0,status:'active',
      createdAt:firebase.firestore.FieldValue.serverTimestamp()
    };
    return _db.collection('yongcha_users').doc(c.user.uid).set(_doc).then(function(){
      if(_CU&&_CU.uid===c.user.uid)return; // onAuthStateChanged ADMINS path may have won the race
      _CU=Object.assign({uid:c.user.uid},_doc);
      _showApp();
    });
  }).catch(function(ex){
    btn.textContent='가입하기';btn.disabled=false;
    err.textContent=ex.code==='auth/email-already-in-use'?'이미 사용 중인 이메일':'오류: '+ex.message;
    err.style.display='block';
  });
}

// ── 앱 표시 ──────────────────────────────────────────────────
function _showApp(){
  document.getElementById('login-screen').style.display='none';
  document.getElementById('app').style.display='flex';
  var type=_CU.type;
  var badge=document.getElementById('hdr-badge');
  badge.textContent=type==='admin'?'관리자':type==='agency'?'대리점':'기사';
  badge.className='hdr-badge '+(type==='admin'?'badge-admin':type==='agency'?'badge-agency':'badge-driver');
  _prefs=_CU.preferences||null;
  _buildNav();
  // 찜 목록을 먼저 캐시한 뒤 홈을 그린다 (카드마다 개별 read 하지 않기 위해)
  _yLoadBookmarks().then(function(){
    return _yRestSync();          // 만료된 휴식 자동 복귀 처리 후 홈을 그린다
  }).then(function(){
    _goPage('home');
    _yHandleDeepLink();
  });
  setTimeout(_yInitFCM,1200);
  setTimeout(_yStartNotifListener,1500);
}

