    const rlParse = (t) => {
      const f={};
      if(/쿠팡/.test(t))f.courier='쿠팡로지스틱스';
      else if(/CJ|씨제이/.test(t))f.courier='CJ대한통운';
      else if(/한진/.test(t))f.courier='한진택배';
      else if(/롯데/.test(t))f.courier='롯데택배';
      else if(/우체국/.test(t))f.courier='우체국';
      else if(/로젠/.test(t))f.courier='로젠택배';
      const vM=t.match(/(\d+)\s*건/);if(vM)f.volume=parseInt(vM[1]);
      const pM=t.match(/(\d+(?:\.\d+)?)\s*만\s*원?/);
      if(pM)f.unitPrice=Math.round(parseFloat(pM[1])*10000);
      else{const p2=t.match(/단가\s*(\d{4,})|(\d{4,})\s*원/);if(p2)f.unitPrice=parseInt(p2[1]||p2[2]);}
      if(/야간|저녁/.test(t))f.workShift='야간';
      else if(/새벽/.test(t))f.workShift='새벽';
      else if(/당일/.test(t))f.workShift='당일';
      else if(/주간|낮/.test(t))f.workShift='주간';
      if(/긴급|급히|오늘/.test(t))f.urgent=true;
      const rem=t.replace(/쿠팡|CJ대한통운|CJ|씨제이|한진택배|한진|롯데택배|롯데|우체국|로젠택배|로젠/g,'').replace(/\d+건|\d+만\s*원|\d+원/g,'').replace(/야간|주간|새벽|당일|저녁|낮|긴급|급히|오늘/g,'').trim();
      const aM=rem.match(/([가-힣]{2,})/);if(aM)f.area=aM[1];
      return f;
    };
