      let result = {};
      try { result = JSON.parse(raw); } catch(e) { const m = raw.match(/\{[\s\S]*\}/); if(m) try { result = JSON.parse(m[0]); } catch(e2) {} }
      return new Response(JSON.stringify({ ok: true, data: result }), { headers: corsH });
